.ambient{position:fixed;inset:0;pointer-events:none;background:radial-gradient(ellipse at 65% -30%,color-mix(in srgb,var(--accent) 10%,transparent),transparent 65%)}
.app{position:relative;height:100svh;min-height:440px;max-width:2600px;margin:0 auto;display:grid;grid-template-rows:96px minmax(0,1fr) 138px;padding:0 32px}
